// ── MCQ QUESTION BANK (100+, easy to challenging, chapter-only) ──
export const BIOLOGY10_MCQS: QuizQuestion[] = [
  { id: 1, question: "Which of the following is used by biologists as the defining criterion for life?", options: ["Visible movement only", "Molecular movement (metabolic activity)", "Presence of a nucleus", "Ability to make sound"], correctAnswer: 1, explanation: "Even organisms that show no visible movement (like a plant) have continuous invisible movement at the molecular level, which biologists use as the true criterion for life." },
  { id: 2, question: "Why do viruses present a controversy regarding whether they are truly 'alive'?", options: ["They are too small to see", "They show no molecular movement until they infect a host cell", "They have no genetic material", "They cannot be crystallised"], correctAnswer: 1, explanation: "Viruses show no independent molecular/metabolic activity outside a host cell, which is why their status as 'living' is debated." },
  { id: 3, question: "Which of these is NOT one of the four life processes discussed in this chapter?", options: ["Nutrition", "Respiration", "Reproduction", "Excretion"], correctAnswer: 2, explanation: "This chapter covers nutrition, respiration, transportation, and excretion. Reproduction is covered as a separate chapter." },
  { id: 4, question: "Why do multicellular organisms need a transportation system that single-celled organisms do not?", options: ["They have more DNA", "Not all their cells are in direct contact with the environment", "They do not respire", "Their cells are larger"], correctAnswer: 1, explanation: "In multicellular organisms, most cells are not in direct contact with the environment, so a transport system is needed to carry food, oxygen, and wastes between the surface and internal cells." },
  { id: 5, question: "The process of transferring an outside energy source (food) into the body is called:", options: ["Respiration", "Nutrition", "Excretion", "Transpiration"], correctAnswer: 1, explanation: "Nutrition is the process of taking in and using food as an energy and material source." },
  { id: 6, question: "Organisms that make their own food using simple inorganic materials are called:", options: ["Heterotrophs", "Autotrophs", "Saprophytes", "Parasites"], correctAnswer: 1, explanation: "Autotrophs (e.g. green plants, some bacteria) synthesise their own food from inorganic CO2 and water." },
  { id: 7, question: "Organisms that depend on complex substances made by other organisms are called:", options: ["Autotrophs", "Heterotrophs", "Photoautotrophs", "Chemoautotrophs"], correctAnswer: 1, explanation: "Heterotrophs cannot make their own food; they consume complex organic material made by other organisms." },
  { id: 8, question: "Which of the following is an autotroph?", options: ["Mushroom", "Green plant", "Tapeworm", "Amoeba"], correctAnswer: 1, explanation: "Green plants carry out photosynthesis and are autotrophic. Mushrooms are saprophytic heterotrophs, tapeworms are parasites, and Amoeba is a heterotroph." },
  { id: 9, question: "The overall raw materials required for photosynthesis are:", options: ["Oxygen and glucose", "Carbon dioxide and water", "Nitrogen and phosphorus", "Starch and glycogen"], correctAnswer: 1, explanation: "Photosynthesis uses carbon dioxide (from air) and water (from soil) as raw materials, in the presence of chlorophyll and sunlight." },
  { id: 10, question: "In the overall photosynthesis equation, the by-product released is:", options: ["Carbon dioxide", "Nitrogen", "Oxygen", "Water vapour only"], correctAnswer: 2, explanation: "6CO2 + 12H2O -> C6H12O6 + 6O2 + 6H2O. Oxygen is released as a by-product." },
  { id: 11, question: "Which pigment is essential for absorbing light energy during photosynthesis?", options: ["Haemoglobin", "Chlorophyll", "Melanin", "Xanthophyll only"], correctAnswer: 1, explanation: "Chlorophyll, present in chloroplasts, absorbs light energy needed to drive photosynthesis." },
  { id: 12, question: "Which of the following is the correct order of events in photosynthesis?", options: ["Reduction of CO2, absorption of light, splitting of water", "Absorption of light, splitting of water, reduction of CO2", "Splitting of water, reduction of CO2, absorption of light", "Absorption of light, reduction of CO2, splitting of water"], correctAnswer: 1, explanation: "First light is absorbed by chlorophyll; this energy splits water into hydrogen and oxygen; the hydrogen is then used to reduce CO2 into carbohydrates." },
  { id: 13, question: "Excess glucose made during photosynthesis is typically stored in plants as:", options: ["Glycogen", "Starch", "Cellulose", "Chitin"], correctAnswer: 1, explanation: "Plants store excess glucose as starch, while animals store excess glucose as glycogen." },
  { id: 14, question: "In desert plants adapted to conserve water, carbon dioxide is typically taken up:", options: ["During the day only", "At night, and processed further using daytime light energy", "Never -- they rely entirely on stored CO2", "Only through their roots"], correctAnswer: 1, explanation: "Certain desert plants (CAM plants) take up CO2 at night when stomata can open with less water loss, storing it as an intermediate that is then processed using light energy during the day." },
  { id: 15, question: "Tiny pores on the leaf surface responsible for gaseous exchange are called:", options: ["Lenticels", "Stomata", "Trichomes", "Bark pores"], correctAnswer: 1, explanation: "Stomata are the small pores, mainly on leaves, through which gases (CO2, O2, water vapour) are exchanged with the atmosphere." },
  { id: 16, question: "The opening and closing of a stomatal pore is regulated by:", options: ["Xylem cells", "Guard cells", "Companion cells", "Epidermal hair cells"], correctAnswer: 1, explanation: "Guard cells surrounding each stomatal pore swell (pore opens) or shrink (pore closes) depending on water content, controlling gas exchange." },
  { id: 17, question: "Why do guard cells sometimes close the stomatal pore even during the day?", options: ["To let in more sunlight", "To prevent excessive loss of water when CO2 is not needed", "To increase photosynthesis", "To allow more oxygen in"], correctAnswer: 1, explanation: "When CO2 is not urgently needed, closing the stomata helps the plant avoid losing too much water through transpiration." },
  { id: 18, question: "In the classic starch-test experiment (Activity 5.1) using a variegated leaf, which parts turn blue-black with iodine after being exposed to light?", options: ["Only the non-green (white) parts", "Only the green (chlorophyll-containing) parts", "The entire leaf uniformly", "Neither part, since starch was destroyed by boiling"], correctAnswer: 1, explanation: "Only the green, chlorophyll-containing regions carry out photosynthesis and form starch, so only those regions turn blue-black with iodine." },
  { id: 19, question: "In the KOH experiment (Activity 5.2) testing the CO2 requirement for photosynthesis, the potassium hydroxide is used to:", options: ["Provide extra CO2", "Absorb CO2 from the air inside the bell jar", "Absorb oxygen", "Increase humidity"], correctAnswer: 1, explanation: "KOH absorbs the CO2 present inside the sealed bell jar, so the enclosed plant has no CO2 available and cannot photosynthesise -- shown by a negative starch test." },
  { id: 20, question: "Apart from carbon dioxide, water, and sunlight, plants also obtain the following raw materials from the soil via their roots:", options: ["Oxygen and hydrogen", "Nitrogen, phosphorus, iron, and magnesium", "Glucose and sucrose", "Starch and cellulose"], correctAnswer: 1, explanation: "Plants absorb essential minerals such as nitrogen, phosphorus, iron, and magnesium from the soil through their roots." },
  { id: 21, question: "Nitrogen absorbed by plant roots is essential mainly for:", options: ["Chlorophyll destruction", "Protein synthesis", "Cellulose breakdown", "Water absorption"], correctAnswer: 1, explanation: "Nitrogen is a key component of amino acids and proteins, so it is essential for protein synthesis in plants." },
  { id: 22, question: "Fungi such as bread moulds and mushrooms obtain nutrition by:", options: ["Photosynthesis", "Breaking down food outside the body and then absorbing it (saprophytic nutrition)", "Parasitism only", "Taking in whole food and digesting it internally"], correctAnswer: 1, explanation: "Fungi are saprophytes -- they secrete digestive enzymes onto their food source, breaking it down externally, then absorb the simpler nutrients." },
  { id: 23, question: "Cuscuta (amar-bel), a plant that derives nutrition from a host plant without immediately killing it, shows:", options: ["Autotrophic nutrition", "Saprophytic nutrition", "Parasitic nutrition", "Holozoic nutrition"], correctAnswer: 2, explanation: "Cuscuta is a classic example of a parasitic plant that derives its nutrition directly from a living host plant." },
  { id: 24, question: "Which of the following is an example of an organism showing parasitic nutrition?", options: ["Mushroom", "Amoeba", "Tapeworm", "Green plant"], correctAnswer: 2, explanation: "Tapeworms live inside a host's intestine and derive nutrition from the host without providing any benefit -- a classic parasite, along with ticks, lice, and leeches." },
  { id: 25, question: "In Amoeba, temporary finger-like extensions used to engulf food particles are called:", options: ["Cilia", "Flagella", "Pseudopodia", "Villi"], correctAnswer: 2, explanation: "Amoeba forms pseudopodia, temporary extensions of the cell surface, which surround and engulf food particles." },
  { id: 26, question: "In Amoeba, the structure formed when pseudopodia fuse around a food particle is called a:", options: ["Nucleus", "Food vacuole", "Contractile vacuole", "Cell wall"], correctAnswer: 1, explanation: "The fused pseudopodia form a food vacuole inside which complex substances are broken down into simpler ones for absorption." },
  { id: 27, question: "How does Paramecium move food to a specific spot on its cell surface for ingestion?", options: ["Using pseudopodia", "Using the beating action of cilia covering its surface", "By diffusion alone", "It has no fixed method of feeding"], correctAnswer: 1, explanation: "Paramecium has a definite shape and uses the coordinated beating of cilia covering its cell surface to sweep food towards a specific spot for ingestion." },
  { id: 28, question: "The long tube in the human body running from the mouth to the anus, with specialised regions for digestion, is called the:", options: ["Trachea", "Alimentary canal", "Aorta", "Ureter"], correctAnswer: 1, explanation: "The alimentary canal is the continuous tube through which food passes and is digested, from mouth to anus." },
  { id: 29, question: "The enzyme present in saliva that begins the digestion of starch is:", options: ["Pepsin", "Salivary amylase", "Trypsin", "Lipase"], correctAnswer: 1, explanation: "Salivary amylase, secreted by the salivary glands, starts breaking down starch into simpler sugars in the mouth." },
  { id: 30, question: "The rhythmic, wave-like muscular contractions that push food along the alimentary canal are called:", options: ["Peristaltic movements", "Osmotic movements", "Systolic movements", "Ciliary movements"], correctAnswer: 0, explanation: "Peristalsis is the rhythmic contraction of the muscular walls of the alimentary canal that pushes food forward." },
  { id: 31, question: "The tube that carries food from the mouth to the stomach is the:", options: ["Trachea", "Oesophagus", "Ureter", "Bronchus"], correctAnswer: 1, explanation: "The oesophagus (food pipe) connects the mouth (via the pharynx) to the stomach." },
  { id: 32, question: "Which of the following is secreted by the gastric glands in the stomach?", options: ["Bile, pepsin, and mucus", "Hydrochloric acid, pepsin, and mucus", "Trypsin, lipase, and bile", "Amylase, HCl, and bile"], correctAnswer: 1, explanation: "Gastric glands secrete HCl (creates acidic medium), pepsin (digests protein), and mucus (protects stomach lining)." },
  { id: 33, question: "The main function of hydrochloric acid in the stomach is to:", options: ["Digest fats directly", "Create the acidic medium pepsin needs and kill ingested bacteria", "Neutralise pepsin", "Absorb nutrients"], correctAnswer: 1, explanation: "HCl makes the stomach acidic (needed for pepsin activity) and also kills many bacteria present in food." },
  { id: 34, question: "Excess secretion of stomach acid, causing discomfort, is commonly known as:", options: ["Gastritis only", "Acidity", "Peristalsis disorder", "Villus inflammation"], correctAnswer: 1, explanation: "Excessive HCl secretion causes the common complaint known as 'acidity'." },
  { id: 35, question: "The muscle that regulates the release of food from the stomach into the small intestine is the:", options: ["Cardiac sphincter", "Pyloric sphincter", "Anal sphincter", "Iris sphincter"], correctAnswer: 1, explanation: "The (pyloric) sphincter muscle at the stomach's exit regulates the release of small amounts of food into the small intestine at a time." },
  { id: 36, question: "Compared to a carnivore, an herbivore's small intestine is usually:", options: ["Shorter, since grass is easy to digest", "Longer, to allow more time to digest cellulose", "Exactly the same length", "Absent entirely"], correctAnswer: 1, explanation: "Cellulose in grass is harder to digest, so herbivores have a longer small intestine to allow more time and surface area for digestion." },
  { id: 37, question: "Bile juice, secreted by the liver, performs which of the following functions in digestion?", options: ["Digests proteins directly", "Emulsifies fats and makes acidic chyme alkaline", "Produces amylase", "Absorbs water"], correctAnswer: 1, explanation: "Bile emulsifies large fat globules into smaller ones and neutralises the acidic food from the stomach so pancreatic enzymes can work effectively." },
  { id: 38, question: "The pancreatic enzyme that digests proteins is:", options: ["Trypsin", "Amylase", "Bile", "Mucin"], correctAnswer: 0, explanation: "Trypsin, secreted in pancreatic juice, digests proteins into simpler peptides/amino acids." },
  { id: 39, question: "The pancreatic enzyme that breaks down emulsified fats is:", options: ["Trypsin", "Lipase", "Pepsin", "Amylase"], correctAnswer: 1, explanation: "Lipase, from pancreatic juice, breaks down emulsified fats into fatty acids and glycerol." },
  { id: 40, question: "Intestinal juice, secreted by glands in the intestinal wall, finally converts complex carbohydrates into:", options: ["Amino acids", "Glucose", "Fatty acids", "Glycerol"], correctAnswer: 1, explanation: "Intestinal juice enzymes convert complex carbohydrates fully into glucose, ready for absorption." },
  { id: 41, question: "Finger-like projections on the inner wall of the small intestine that increase surface area for absorption are called:", options: ["Cilia", "Villi", "Rugae", "Papillae"], correctAnswer: 1, explanation: "Villi are tiny finger-like projections richly supplied with blood vessels that vastly increase the absorptive surface area of the small intestine." },
  { id: 42, question: "The main function of the large intestine is to:", options: ["Digest proteins", "Absorb more water from the undigested food", "Secrete bile", "Store urine"], correctAnswer: 1, explanation: "The large intestine mainly absorbs water from the remaining undigested material, forming the waste into semi-solid faeces." },
  { id: 43, question: "Undigested waste material leaves the body through the anus, regulated by the:", options: ["Pyloric sphincter", "Anal sphincter", "Bowman's capsule", "Diaphragm"], correctAnswer: 1, explanation: "The anal sphincter regulates the voluntary release of waste material from the body." },
  { id: 44, question: "Dental plaque, which can lead to tooth decay, is mainly made up of:", options: ["Bone fragments", "Bacterial cells and food particles stuck on teeth", "Excess saliva", "Enamel"], correctAnswer: 1, explanation: "Dental plaque is formed when bacterial cells and leftover food particles stick to teeth; bacteria then act on sugars to produce acid that damages enamel." },
  { id: 45, question: "The first step of glucose breakdown, common to all organisms, converts glucose into:", options: ["Lactic acid", "Pyruvate", "Ethanol", "Carbon dioxide"], correctAnswer: 1, explanation: "In the cytoplasm, glucose (6-carbon) is broken down into pyruvate (3-carbon), releasing some energy -- this step is common to every organism." },
  { id: 46, question: "The first step of glucose breakdown occurs in the:", options: ["Mitochondria", "Nucleus", "Cytoplasm", "Chloroplast"], correctAnswer: 2, explanation: "Glycolysis, the splitting of glucose into pyruvate, occurs in the cytoplasm." },
  { id: 47, question: "In the presence of oxygen, pyruvate is broken down inside the mitochondria into:", options: ["Ethanol and CO2", "Lactic acid", "Carbon dioxide, water, and energy", "Glucose"], correctAnswer: 2, explanation: "Aerobic respiration in the mitochondria fully breaks pyruvate down into CO2, water, and a large amount of energy." },
  { id: 48, question: "In yeast, under anaerobic conditions, pyruvate is converted into:", options: ["Lactic acid and energy", "Ethanol, carbon dioxide, and energy", "Carbon dioxide and water only", "Glucose and oxygen"], correctAnswer: 1, explanation: "Yeast carries out fermentation, converting pyruvate anaerobically into ethanol and CO2, releasing a smaller amount of energy." },
  { id: 49, question: "In human muscle cells during vigorous exercise, a lack of oxygen causes pyruvate to be converted into:", options: ["Ethanol", "Lactic acid", "Glucose", "Starch"], correctAnswer: 1, explanation: "Under low-oxygen conditions, muscle cells convert pyruvate anaerobically into lactic acid, whose build-up causes muscle cramps." },
  { id: 50, question: "Muscle cramps after intense exercise are caused by the build-up of:", options: ["Glucose", "Lactic acid", "Ethanol", "Carbon dioxide"], correctAnswer: 1, explanation: "Accumulation of lactic acid in muscle cells (from anaerobic respiration) causes the sensation of cramping." },
  { id: 51, question: "Compared to anaerobic respiration, aerobic respiration releases:", options: ["The same amount of energy", "Much less energy", "Much more energy", "No energy at all"], correctAnswer: 2, explanation: "Aerobic respiration fully oxidises glucose using oxygen, releasing far more energy than the incomplete breakdown in anaerobic respiration." },
  { id: 52, question: "ATP is best described as:", options: ["A structural protein", "The energy currency of the cell", "A type of enzyme only", "A waste product of respiration"], correctAnswer: 1, explanation: "ATP (adenosine triphosphate) stores and supplies usable chemical energy for cellular activities, so it is called the cell's energy currency." },
  { id: 53, question: "Breaking the terminal phosphate bond of ATP (using water) releases energy that is used to drive:", options: ["Only muscle contraction", "Endothermic reactions in the cell", "Photosynthesis exclusively", "DNA replication only"], correctAnswer: 1, explanation: "The energy released from ATP's terminal phosphate bond powers many endothermic (energy-requiring) cellular reactions, from muscle contraction to nerve impulses." },
  { id: 54, question: "At night, plants primarily release which gas as a result of respiration?", options: ["Oxygen", "Carbon dioxide", "Nitrogen", "Hydrogen"], correctAnswer: 1, explanation: "At night, without photosynthesis happening, the CO2 produced by respiration is not consumed and is released as the major gas exchange event." },
  { id: 55, question: "During the day, plants mainly release which gas, since respiratory CO2 gets used up in photosynthesis?", options: ["Nitrogen", "Oxygen", "Carbon dioxide", "Methane"], correctAnswer: 1, explanation: "During the day, CO2 from respiration is consumed by photosynthesis, so oxygen release becomes the dominant visible gas exchange event." },
  { id: 56, question: "Fish obtain dissolved oxygen from water using:", options: ["Lungs", "Gills", "Skin only", "Trachea"], correctAnswer: 1, explanation: "Fish take in water through the mouth and force it past the gills, where dissolved oxygen is absorbed into the blood." },
  { id: 57, question: "Aquatic organisms generally have a faster breathing rate than terrestrial organisms because:", options: ["Water contains more oxygen than air", "The amount of dissolved oxygen in water is much lower than in air", "Fish have smaller lungs", "Aquatic organisms are always smaller"], correctAnswer: 1, explanation: "Since water holds far less dissolved oxygen than the atmosphere, aquatic organisms must move much more water past their gills, resulting in a faster breathing rate." },
  { id: 58, question: "In the human respiratory pathway, air travels through structures in which correct order?", options: ["Trachea, pharynx, larynx, bronchi", "Nasal passage, pharynx, larynx, trachea, bronchi", "Larynx, nasal passage, trachea, alveoli", "Bronchi, trachea, larynx, pharynx"], correctAnswer: 1, explanation: "Air passes: nasal passage -> pharynx -> larynx -> trachea -> bronchi -> bronchioles -> alveoli." },
  { id: 59, question: "The rings of cartilage present in the trachea function to:", options: ["Produce sound", "Prevent the trachea from collapsing", "Filter incoming air", "Warm the air"], correctAnswer: 1, explanation: "Cartilage rings keep the trachea's walls firm so it doesn't collapse, keeping the airway open." },
  { id: 60, question: "Fine hairs and mucus lining the nasal passage function to:", options: ["Warm the blood", "Filter dust and germs from incoming air", "Produce sound", "Absorb oxygen"], correctAnswer: 1, explanation: "Fine hairs and mucus trap dust particles and germs, filtering the air before it travels deeper into the respiratory system." },
  { id: 61, question: "The balloon-like structures where actual gas exchange occurs in the lungs are called:", options: ["Bronchioles", "Alveoli", "Bronchi", "Nasal passages"], correctAnswer: 1, explanation: "Alveoli are the tiny, thin-walled, richly vascularised sacs where oxygen and carbon dioxide are actually exchanged with the blood." },
  { id: 62, question: "During inhalation, which of the following occurs?", options: ["Ribs move down and diaphragm domes upward", "Ribs lift up and the diaphragm flattens, enlarging the chest cavity", "The chest cavity shrinks", "The diaphragm has no role"], correctAnswer: 1, explanation: "During inhalation, the ribs move up and outward and the diaphragm flattens, enlarging the chest cavity and drawing air into the lungs." },
  { id: 63, question: "Why do the lungs always retain some residual air volume even after exhaling fully?", options: ["To reduce weight", "To allow enough time for O2 absorption and CO2 release", "Because the alveoli cannot fully empty due to a blockage", "It has no functional purpose"], correctAnswer: 1, explanation: "Retaining residual air allows more efficient, continuous gas exchange, since the lungs never have to start from completely empty." },
  { id: 64, question: "Haemoglobin, the respiratory pigment in human blood, is present in:", options: ["Blood plasma", "Red blood cells", "White blood cells", "Platelets"], correctAnswer: 1, explanation: "Haemoglobin is packed inside red blood cells and has a high affinity for binding oxygen." },
  { id: 65, question: "Compared to oxygen, carbon dioxide is transported in blood mostly:", options: ["Bound to haemoglobin, like oxygen", "Dissolved in the blood plasma", "As a solid precipitate", "It is not transported at all"], correctAnswer: 1, explanation: "CO2 is far more soluble in water than O2, so it is mostly transported simply dissolved in the blood plasma rather than needing a dedicated carrier." },
  { id: 66, question: "Smoking damages the respiratory system partly by destroying:", options: ["Alveoli's blood vessels only", "Cilia in the upper respiratory tract that normally remove germs and dust", "The rib cage", "The oesophagus"], correctAnswer: 1, explanation: "Smoking destroys the cilia that normally sweep germs, dust, and chemicals out of the airway, allowing them to enter the lungs and cause infection or cancer." },
  { id: 67, question: "The fluid connective tissue that transports substances throughout the human body is:", options: ["Lymph", "Blood", "Bile", "Mucus"], correctAnswer: 1, explanation: "Blood is the fluid connective tissue responsible for transporting food, gases, and wastes throughout the body." },
  { id: 68, question: "The liquid component of blood, which transports dissolved food, CO2, and nitrogenous waste, is:", options: ["Plasma", "Platelets", "Red blood cells", "White blood cells"], correctAnswer: 0, explanation: "Plasma is the fluid part of blood in which food, CO2, and nitrogenous wastes are transported in dissolved form." },
  { id: 69, question: "Which blood component is primarily responsible for carrying oxygen?", options: ["Plasma", "Platelets", "Red blood cells", "White blood cells"], correctAnswer: 2, explanation: "Red blood cells, carrying haemoglobin, are responsible for transporting oxygen through the blood." },
  { id: 70, question: "Blood clotting at the site of an injury is carried out mainly by:", options: ["Red blood cells", "White blood cells", "Platelets", "Plasma proteins alone"], correctAnswer: 2, explanation: "Platelets circulate in the blood and gather at injury sites to plug leaks and form clots." },
  { id: 71, question: "In the human heart, blood rich in oxygen from the lungs first enters the:", options: ["Right atrium", "Left atrium", "Right ventricle", "Left ventricle"], correctAnswer: 1, explanation: "Oxygenated blood from the lungs enters the left atrium first, before moving to the left ventricle to be pumped to the body." },
  { id: 72, question: "The chamber of the heart that pumps oxygenated blood out to the entire body is the:", options: ["Right atrium", "Right ventricle", "Left atrium", "Left ventricle"], correctAnswer: 3, explanation: "The left ventricle pumps oxygenated blood out through the aorta to the rest of the body." },
  { id: 73, question: "Deoxygenated blood from the body first enters the heart at the:", options: ["Left atrium", "Right atrium", "Left ventricle", "Right ventricle"], correctAnswer: 1, explanation: "Deoxygenated blood returning from the body first enters the right atrium." },
  { id: 74, question: "The right ventricle pumps deoxygenated blood to the:", options: ["Rest of the body", "Lungs, for oxygenation", "Left atrium directly", "Kidneys only"], correctAnswer: 1, explanation: "The right ventricle pumps deoxygenated blood to the lungs, where it picks up oxygen." },
  { id: 75, question: "Why do ventricles have thicker, more muscular walls than atria?", options: ["They store more blood", "They must pump blood over longer distances, needing more force", "They contain more valves", "Atria have no muscle at all"], correctAnswer: 1, explanation: "Ventricles need to generate enough force to pump blood to the lungs or the entire body, so their walls are thicker and more muscular than the atria, which only need to push blood a short distance into the ventricles." },
  { id: 76, question: "Valves in the heart function to:", options: ["Produce the heartbeat sound only", "Prevent the backflow of blood", "Filter the blood", "Add oxygen to the blood"], correctAnswer: 1, explanation: "Valves ensure blood only flows in one direction through the heart's chambers, preventing backflow during contraction." },
  { id: 77, question: "Which animal group has a two-chambered heart with single circulation?", options: ["Mammals", "Birds", "Fish", "Amphibians"], correctAnswer: 2, explanation: "Fish have a two-chambered heart; blood is pumped to the gills for oxygenation and then goes directly to the body, passing through the heart only once per cycle -- single circulation." },
  { id: 78, question: "Amphibians and many reptiles have hearts that:", options: ["Have four completely separate chambers", "Have three chambers, tolerating some mixing of oxygenated and deoxygenated blood", "Have only one chamber", "Have no septum at all separating any chambers"], correctAnswer: 1, explanation: "Amphibians and many reptiles have three-chambered hearts, allowing some mixing of oxygenated and deoxygenated blood, tolerable because their body temperature depends on the environment." },
  { id: 79, question: "The pressure exerted by blood against the walls of blood vessels is called:", options: ["Osmotic pressure", "Blood pressure", "Turgor pressure", "Root pressure"], correctAnswer: 1, explanation: "Blood pressure is the force exerted by circulating blood against the walls of blood vessels." },
  { id: 80, question: "Systolic blood pressure refers to the pressure during:", options: ["Ventricular relaxation", "Ventricular contraction", "Atrial relaxation only", "Complete cardiac arrest"], correctAnswer: 1, explanation: "Systolic pressure is measured during ventricular systole, i.e. when the ventricles contract and pump blood out." },
  { id: 81, question: "A normal healthy adult's blood pressure is often quoted as approximately:", options: ["80/120 mm Hg", "120/80 mm Hg", "180/120 mm Hg", "60/40 mm Hg"], correctAnswer: 1, explanation: "Normal blood pressure is typically quoted as about 120 mm Hg systolic over 80 mm Hg diastolic." },
  { id: 82, question: "Blood pressure is measured using an instrument called a:", options: ["Stethoscope only", "Sphygmomanometer", "Thermometer", "Spirometer"], correctAnswer: 1, explanation: "A sphygmomanometer, typically used with a stethoscope, is the instrument used to measure blood pressure." },
  { id: 83, question: "Hypertension (high blood pressure) is generally caused by:", options: ["Dilation of arterioles reducing resistance", "Constriction of arterioles increasing resistance to blood flow", "A drop in heart rate to zero", "Excess platelets alone"], correctAnswer: 1, explanation: "Constriction (narrowing) of arterioles increases resistance to blood flow, raising blood pressure -- this is hypertension." },
  { id: 84, question: "Blood vessels that carry blood away from the heart, under high pressure, with thick elastic walls, are:", options: ["Veins", "Arteries", "Capillaries", "Lymph vessels"], correctAnswer: 1, explanation: "Arteries carry blood away from the heart under high pressure, so they have thick, elastic walls." },
  { id: 85, question: "Blood vessels that carry blood back to the heart, and contain valves to prevent backflow, are:", options: ["Arteries", "Veins", "Capillaries", "Nephrons"], correctAnswer: 1, explanation: "Veins carry blood back to the heart at lower pressure and have valves to ensure one-way flow." },
  { id: 86, question: "The blood vessels with walls only one cell thick, allowing material exchange with tissue cells, are:", options: ["Arteries", "Veins", "Capillaries", "Venules only"], correctAnswer: 2, explanation: "Capillaries have extremely thin, single-cell-thick walls, which allows efficient exchange of materials between blood and body cells." },
  { id: 87, question: "Lymph (tissue fluid) is formed when:", options: ["Red blood cells escape through capillary pores", "Plasma, some proteins, and cells escape through capillary pores into the intercellular space", "Platelets clump together", "Bile mixes with blood"], correctAnswer: 1, explanation: "Lymph is formed from plasma, blood cells, and some proteins that escape through capillary walls into the surrounding tissue spaces." },
  { id: 88, question: "One important function of the lymphatic system is to:", options: ["Produce haemoglobin", "Carry absorbed fat from the intestine and drain excess tissue fluid back into the blood", "Filter urine", "Store bile"], correctAnswer: 1, explanation: "Lymph carries digested and absorbed fat from the intestine into the bloodstream, and also drains excess fluid from tissues back into the blood." },
  { id: 89, question: "Which plant tissue transports water and minerals from the roots upward?", options: ["Phloem", "Xylem", "Epidermis", "Cortex"], correctAnswer: 1, explanation: "Xylem tissue conducts water and dissolved minerals upward from the roots to the rest of the plant." },
  { id: 90, question: "Which plant tissue transports the products of photosynthesis to other parts of the plant?", options: ["Xylem", "Phloem", "Epidermis", "Meristem"], correctAnswer: 1, explanation: "Phloem tissue transports soluble food (mainly sucrose) from the leaves to other parts of the plant, a process called translocation." },
  { id: 91, question: "The upward pushing force created when roots actively absorb ions from the soil, causing water to move into the root xylem, is called:", options: ["Transpiration pull", "Root pressure", "Osmotic lag", "Turgor pressure"], correctAnswer: 1, explanation: "Root pressure is generated by active ion uptake in roots, which draws water into the xylem, pushing it upward -- most important at night when stomata are closed." },
  { id: 92, question: "The main driving force for water movement up a tall tree during the day is:", options: ["Root pressure alone", "Transpiration pull", "Gravity", "Blood pressure equivalent in plants"], correctAnswer: 1, explanation: "During the day, evaporation of water from leaves (transpiration) through open stomata creates a suction (transpiration pull) that draws water up through the xylem." },
  { id: 93, question: "The loss of water vapour from the aerial parts of a plant, mainly through stomata, is called:", options: ["Translocation", "Transpiration", "Osmoregulation", "Guttation"], correctAnswer: 1, explanation: "Transpiration is the loss of water vapour from a plant's aerial surfaces, mainly through open stomata." },
  { id: 94, question: "Apart from helping pull water upward, transpiration also helps in:", options: ["Digestion of starch", "Regulating the plant's temperature", "Producing chlorophyll", "Forming lymph"], correctAnswer: 1, explanation: "As water evaporates during transpiration, it has a cooling effect, helping regulate the plant's temperature." },
  { id: 95, question: "In phloem, sucrose is loaded into sieve tubes using energy from:", options: ["Sunlight directly", "ATP", "Root pressure", "Transpiration"], correctAnswer: 1, explanation: "Unlike water movement in xylem, loading sucrose into phloem sieve tubes actively uses ATP energy." },
  { id: 96, question: "In humans, the pair of organs responsible for filtering nitrogenous wastes from blood are the:", options: ["Lungs", "Kidneys", "Liver", "Pancreas"], correctAnswer: 1, explanation: "The kidneys are the primary excretory organs, filtering nitrogenous wastes such as urea from the blood." },
  { id: 97, question: "Urine formed in the kidneys travels to the urinary bladder through the:", options: ["Urethra", "Ureters", "Renal artery", "Renal vein"], correctAnswer: 1, explanation: "Urine flows from each kidney through a ureter into the urinary bladder for storage." },
  { id: 98, question: "The basic structural and functional filtration unit of the kidney is the:", options: ["Alveolus", "Nephron", "Villus", "Neuron"], correctAnswer: 1, explanation: "Each kidney contains millions of nephrons, the basic filtration units responsible for forming urine." },
  { id: 99, question: "In a nephron, the cluster of thin-walled blood capillaries where filtration begins is the:", options: ["Bowman's capsule", "Glomerulus", "Collecting duct", "Renal pelvis"], correctAnswer: 1, explanation: "The glomerulus is the network of fine blood capillaries where blood is first filtered; it is enclosed by the Bowman's capsule." },
  { id: 100, question: "Useful substances like glucose, amino acids, and most water are returned to the blood from the nephron's filtrate through:", options: ["Selective reabsorption along the tubule", "Direct diffusion through the ureter", "The urinary bladder wall", "The renal artery only"], correctAnswer: 0, explanation: "As filtrate flows along the nephron's tubule, useful substances are selectively reabsorbed back into the surrounding blood capillaries." },
  { id: 101, question: "Roughly how much of the initial ~180 litres/day of filtrate formed in the kidneys is actually excreted as urine?", options: ["Almost all of it (~180 L/day)", "Only about 1-2 litres/day, the rest is reabsorbed", "Exactly half", "None -- it is all reabsorbed"], correctAnswer: 1, explanation: "Although ~180 litres of filtrate is formed daily, the vast majority of water is reabsorbed along the tubule, leaving only about 1-2 litres actually excreted as urine." },
  { id: 102, question: "An artificial kidney machine removes nitrogenous wastes from a patient's blood through a process called:", options: ["Osmoregulation", "Dialysis", "Translocation", "Transpiration"], correctAnswer: 1, explanation: "Dialysis (hemodialysis) uses a machine with a selectively permeable membrane to remove nitrogenous wastes from blood when the kidneys fail." },
  { id: 103, question: "In hemodialysis, how does the composition of the dialysing fluid compare to normal blood plasma?", options: ["Identical in every way, including urea content", "Same osmotic pressure as blood, but without nitrogenous wastes", "Pure distilled water only", "Much higher urea concentration than blood"], correctAnswer: 1, explanation: "The dialysing fluid is kept at the same osmotic pressure as blood but has no nitrogenous wastes, so wastes diffuse out of the patient's blood into the fluid, down their concentration gradient." },
  { id: 104, question: "Compared to animals, plants deal with excess oxygen produced during photosynthesis by:", options: ["Storing it permanently in vacuoles", "Simply releasing it, since it can also be considered a waste product", "Converting it entirely to CO2", "Storing it as resin"], correctAnswer: 1, explanation: "The chapter notes that oxygen produced during photosynthesis can itself be considered a waste product in plants, and is simply released via gas exchange." },
  { id: 105, question: "Which of these is NOT a method plants use to get rid of excretory products?", options: ["Storing waste in vacuoles", "Shedding leaves that have accumulated waste", "Filtering waste through a nephron-like organ", "Storing waste as resins and gums, especially in old xylem"], correctAnswer: 2, explanation: "Plants have no nephron-like filtering organ; instead they store waste in vacuoles, shed waste-laden leaves, store waste as resins/gums, or excrete it into the soil." },
  { id: 106, question: "A student observes that a potted plant kept in the dark for three days shows a negative starch test, but after 6 hours in sunlight it tests positive. This best demonstrates that:", options: ["Starch forms only in darkness", "Light is necessary for starch (food) formation via photosynthesis", "Water alone is sufficient for starch formation", "Starch formation does not need chlorophyll"], correctAnswer: 1, explanation: "The change from negative to positive after light exposure directly demonstrates that light energy is required for photosynthesis to occur and starch to form." },
  { id: 107, question: "If the septum separating the two sides of a mammalian heart were damaged, allowing blood to mix, the most likely direct consequence would be:", options: ["Increased efficiency of oxygen delivery to the body", "Reduced oxygen-carrying efficiency of blood reaching body tissues", "No effect at all on the body", "Immediate stoppage of the heartbeat"], correctAnswer: 1, explanation: "Mixing of oxygenated and deoxygenated blood reduces the oxygen concentration of blood sent to the body, lowering the efficiency of oxygen delivery -- exactly why the septum normally keeps them separate." },
];

// ── QUESTION BANK: VERY SHORT ANSWER (2 MARKS) ──
export const BIOLOGY10_VERY_SHORT: ShortQuestion[] = [
  { id: 1, question: "Define nutrition.", answer: "Nutrition is the process by which an organism takes in food (its source of energy and raw materials) from outside the body and uses it for energy and growth.", keyPoints: ["Intake of food from outside", "Provides energy and raw materials"] },
  { id: 2, question: "Differentiate between autotrophic and heterotrophic nutrition in one line each.", answer: "Autotrophic nutrition is the making of food internally from simple inorganic substances (CO2, water) using external energy like sunlight. Heterotrophic nutrition is taking in complex food already made by other organisms.", keyPoints: ["Autotroph: makes own food", "Heterotroph: consumes ready-made food"] },
  { id: 3, question: "Name the raw materials required for photosynthesis and the by-product released.", answer: "Photosynthesis requires carbon dioxide and water as raw materials (with chlorophyll and sunlight), and releases oxygen as a by-product.", keyPoints: ["Raw materials: CO2 and water", "By-product: oxygen"] },
  { id: 4, question: "What is the role of guard cells?", answer: "Guard cells surround each stomatal pore and regulate its opening and closing by swelling (pore opens) or shrinking (pore closes), controlling gas exchange and water loss.", keyPoints: ["Regulate stomatal opening/closing", "Control gas exchange and water loss"] },
  { id: 5, question: "Name the type of nutrition shown by Cuscuta (amar-bel) and one other example of the same type.", answer: "Cuscuta shows parasitic nutrition. Other examples include tapeworms, ticks, and leeches, which derive nutrition from a host organism.", keyPoints: ["Parasitic nutrition", "Other examples: tapeworm, ticks, leeches"] },
  { id: 6, question: "How does Amoeba take in its food?", answer: "Amoeba puts out temporary finger-like extensions called pseudopodia, which surround a food particle and fuse to form a food vacuole, inside which the food is digested.", keyPoints: ["Pseudopodia engulf food", "Forms a food vacuole"] },
  { id: 7, question: "Name the enzyme present in saliva and state its function.", answer: "Saliva contains salivary amylase, an enzyme that breaks down starch into simpler sugars, beginning carbohydrate digestion in the mouth.", keyPoints: ["Enzyme: salivary amylase", "Function: breaks starch into sugars"] },
  { id: 8, question: "What is the function of bile juice in digestion?", answer: "Bile juice, secreted by the liver, emulsifies large fat globules into smaller droplets (increasing surface area for enzyme action) and makes the acidic food from the stomach alkaline for pancreatic enzymes to act.", keyPoints: ["Emulsifies fats", "Makes chyme alkaline for pancreatic enzymes"] },
  { id: 9, question: "What are villi and what is their function?", answer: "Villi are finger-like projections on the inner wall of the small intestine that increase its surface area and are richly supplied with blood vessels, allowing efficient absorption of digested food into the blood.", keyPoints: ["Finger-like projections in small intestine", "Increase surface area for absorption"] },
  { id: 10, question: "Where does the first, common step of glucose breakdown occur, and what is produced?", answer: "The first step occurs in the cytoplasm of the cell, where glucose (a six-carbon molecule) is broken down into pyruvate (a three-carbon molecule), releasing some energy.", keyPoints: ["Occurs in the cytoplasm", "Glucose broken into pyruvate"] },
  { id: 11, question: "What happens to pyruvate in the absence of oxygen in yeast cells?", answer: "In yeast, in the absence of oxygen, pyruvate is converted into ethanol and carbon dioxide, releasing a relatively small amount of energy -- this process is called fermentation.", keyPoints: ["Pyruvate -> ethanol + CO2", "Anaerobic; less energy released"] },
  { id: 12, question: "Why do our muscles sometimes cramp during vigorous exercise?", answer: "During vigorous exercise, muscle cells may not get enough oxygen, so they respire anaerobically, converting pyruvate into lactic acid. The build-up of lactic acid causes muscle cramps.", keyPoints: ["Anaerobic respiration in low-oxygen muscle cells", "Lactic acid build-up causes cramps"] },
  { id: 13, question: "What is ATP and why is it called the energy currency of the cell?", answer: "ATP (adenosine triphosphate) is a molecule that stores usable chemical energy released during respiration. It is called the cell's energy currency because breaking its terminal phosphate bond releases energy that powers many different cellular activities.", keyPoints: ["Stores usable chemical energy", "Powers cellular activities when broken down"] },
  { id: 14, question: "Why do aquatic organisms generally have a faster rate of breathing than terrestrial organisms?", answer: "Water contains a much lower concentration of dissolved oxygen than air, so aquatic organisms must move a much larger volume of water past their respiratory surface (gills) to obtain sufficient oxygen, resulting in a faster breathing rate.", keyPoints: ["Water has less dissolved oxygen than air", "Faster breathing compensates for this"] },
  { id: 15, question: "What is the function of the rings of cartilage present in the trachea?", answer: "The cartilage rings keep the walls of the trachea from collapsing, ensuring the airway always stays open for the smooth passage of air.", keyPoints: ["Prevent trachea from collapsing", "Keep airway open"] },
  { id: 16, question: "Why do the lungs always retain a residual volume of air, even after exhaling as much as possible?", answer: "Retaining some residual air gives the lungs sufficient time to absorb oxygen and release carbon dioxide continuously and efficiently, rather than starting gas exchange from empty with every breath.", keyPoints: ["Allows continuous, efficient gas exchange", "Prevents lungs emptying completely between breaths"] },
  { id: 17, question: "What is haemoglobin and where is it found?", answer: "Haemoglobin is the respiratory pigment present in the red blood cells of humans. It has a high affinity for oxygen and is responsible for carrying oxygen from the lungs to all body tissues.", keyPoints: ["Respiratory pigment in red blood cells", "Carries oxygen to body tissues"] },
  { id: 18, question: "Name the four chambers of the human heart.", answer: "The human heart has four chambers: the right atrium, right ventricle, left atrium, and left ventricle.", keyPoints: ["Right atrium and right ventricle", "Left atrium and left ventricle"] },
  { id: 19, question: "What is the function of valves present in the heart and veins?", answer: "Valves ensure that blood flows only in one direction, preventing it from flowing backward, both within the chambers of the heart and along veins carrying blood back to the heart.", keyPoints: ["Ensure one-directional blood flow", "Prevent backflow of blood"] },
  { id: 20, question: "Differentiate between systolic and diastolic blood pressure.", answer: "Systolic pressure is the blood pressure recorded during ventricular contraction (systole), normally about 120 mm Hg. Diastolic pressure is the blood pressure recorded during ventricular relaxation (diastole), normally about 80 mm Hg.", keyPoints: ["Systolic: during contraction (~120 mm Hg)", "Diastolic: during relaxation (~80 mm Hg)"] },
  { id: 21, question: "Name the blood vessel type with walls only one cell thick, and state its significance.", answer: "Capillaries have walls only one cell thick, which allows for efficient exchange of substances like oxygen, carbon dioxide, and nutrients directly between blood and the surrounding body cells.", keyPoints: ["Capillaries: walls one cell thick", "Allow efficient exchange with tissue cells"] },
  { id: 22, question: "What is lymph and how is it formed?", answer: "Lymph, also called tissue fluid, is formed when plasma, some proteins, and blood cells escape through the pores of capillary walls into the surrounding intercellular spaces.", keyPoints: ["Formed from plasma escaping capillary pores", "Also called tissue fluid"] },
  { id: 23, question: "Name the two conducting tissues found in vascular plants and what each transports.", answer: "Vascular plants have xylem, which transports water and minerals upward from the roots, and phloem, which transports the soluble products of photosynthesis (food) to other parts of the plant.", keyPoints: ["Xylem: water and minerals", "Phloem: food (photosynthetic products)"] },
  { id: 24, question: "What is transpiration and name one function it performs besides pulling water upward.", answer: "Transpiration is the loss of water vapour from the aerial parts of a plant, mainly through stomata. Besides creating suction to pull water upward through the xylem, it also helps regulate the plant's temperature.", keyPoints: ["Loss of water vapour through stomata", "Also helps regulate plant temperature"] },
  { id: 25, question: "Why is root pressure more important at night than during the day?", answer: "At night, the stomata are closed, so transpiration pull is minimal. Root pressure, generated by active ion uptake in the roots, becomes the more significant force pushing water upward through the xylem at that time.", keyPoints: ["Stomata closed at night, low transpiration", "Root pressure becomes the dominant driving force"] },
  { id: 26, question: "Name the excretory organs in human beings.", answer: "The human excretory system consists of a pair of kidneys, a pair of ureters, a urinary bladder, and a urethra.", keyPoints: ["Kidneys, ureters", "Urinary bladder, urethra"] },
  { id: 27, question: "What is a nephron and where is it located?", answer: "A nephron is the basic structural and functional filtration unit of the kidney. Each kidney contains a very large number of nephrons, which together filter blood and form urine.", keyPoints: ["Basic filtration unit of the kidney", "Present in very large numbers in each kidney"] },
  { id: 28, question: "State two substances that are selectively reabsorbed back into the blood as filtrate flows along the nephron's tubule.", answer: "Useful substances such as glucose and amino acids (along with most of the water and salts) are selectively reabsorbed back into the blood as filtrate flows along the nephron's tubule.", keyPoints: ["Glucose and amino acids reabsorbed", "Most water and salts also reabsorbed"] },
  { id: 29, question: "What is dialysis and when is it needed?", answer: "Dialysis is a mechanism, using an artificial kidney machine, that removes nitrogenous wastes from a patient's blood when the kidneys fail to function properly, preventing the build-up of poisonous waste.", keyPoints: ["Removes nitrogenous wastes via a machine", "Needed when kidney function fails"] },
  { id: 30, question: "State any two ways in which plants get rid of excretory products.", answer: "Plants remove excess water via transpiration, store waste in cellular vacuoles or in leaves that are later shed, store waste as resins and gums (especially in old xylem), or excrete some waste into the surrounding soil.", keyPoints: ["Transpiration removes excess water", "Waste stored in vacuoles / shed leaves / resins"] },
];

// ── QUESTION BANK: SHORT ANSWER (3 MARKS) ──
export const BIOLOGY10_SHORT: ShortQuestion[] = [
  { id: 1, question: "Explain why multicellular organisms need a transportation system, while unicellular organisms do not.", answer: "In a unicellular organism, the entire cell surface is in direct contact with the environment, so simple diffusion is enough to exchange food, gases, and wastes. In a multicellular organism, most cells are located deep inside the body, far from the surface, so diffusion alone cannot supply them fast enough. A dedicated transportation system is therefore needed to carry food, oxygen, and wastes between the body surface and every internal cell.", keyPoints: ["Unicellular: whole surface exchanges directly", "Multicellular: internal cells too far for diffusion", "Needs transport system to reach internal cells"] },
  { id: 2, question: "Describe the three main events of photosynthesis.", answer: "Photosynthesis involves three key events: first, chlorophyll in the chloroplasts absorbs light energy; second, this light energy is converted into chemical energy, and water molecules are split into hydrogen and oxygen; third, the released hydrogen is used to reduce carbon dioxide into carbohydrates. These steps need not occur immediately one after another.", keyPoints: ["Absorption of light energy by chlorophyll", "Conversion to chemical energy + splitting of water", "Reduction of CO2 to carbohydrates"] },
  { id: 3, question: "Describe the process of digestion of food in the mouth.", answer: "In the mouth, teeth crush and grind food into smaller pieces. Saliva, secreted by the salivary glands, wets the food for smooth swallowing and contains salivary amylase, an enzyme that begins breaking down starch into simple sugars. The muscular tongue mixes the food thoroughly with saliva before it is swallowed.", keyPoints: ["Teeth crush food into smaller pieces", "Saliva wets food and contains salivary amylase", "Tongue mixes food and saliva"] },
  { id: 4, question: "Describe the role of the stomach in digestion.", answer: "The stomach is a large, expandable, muscular organ whose walls churn and mix food with digestive juices. Gastric glands in its wall secrete hydrochloric acid, which creates the acidic medium needed for the enzyme pepsin to digest proteins and also kills bacteria; and mucus, which protects the stomach's own lining from the acid. Partly digested food is then released in small amounts into the small intestine.", keyPoints: ["Muscular churning mixes food with gastric juice", "HCl: acidic medium for pepsin, kills bacteria", "Mucus protects the stomach lining"] },
  { id: 5, question: "Explain the role of the pancreas in digestion.", answer: "The pancreas secretes pancreatic juice into the small intestine, which contains the enzyme trypsin to digest proteins and lipase to break down emulsified fats into fatty acids and glycerol. This makes the pancreas essential for the digestion of both proteins and fats in the small intestine.", keyPoints: ["Secretes pancreatic juice into small intestine", "Trypsin digests proteins", "Lipase breaks down fats"] },
  { id: 6, question: "Why is the small intestine considered the site of complete digestion, and how is it adapted for absorption?", answer: "The small intestine receives secretions from the liver (bile) and pancreas (pancreatic juice), along with its own intestinal juice, which together complete the digestion of carbohydrates, proteins, and fats into simple, absorbable molecules. It is highly coiled to fit a great length in a small space, and its inner wall is covered with villi -- finger-like, blood-vessel-rich projections that vastly increase surface area for absorbing the digested food into the blood.", keyPoints: ["Receives bile and pancreatic juice; completes digestion", "Long, coiled to increase length within the body", "Villi increase surface area for absorption"] },
  { id: 7, question: "Compare the length of the small intestine in herbivores and carnivores, with reasons.", answer: "Herbivores, which eat grass and other plant material containing cellulose that is hard to digest, have a much longer small intestine to allow more time and surface area for cellulose digestion. Carnivores, such as tigers, eat meat, which is comparatively easier to digest, so their small intestine is shorter.", keyPoints: ["Herbivores: longer intestine, cellulose hard to digest", "Carnivores: shorter intestine, meat easier to digest", "Length adapted to diet type"] },
  { id: 8, question: "Explain the three pathways by which pyruvate can be broken down, with the organism/location for each.", answer: "Pyruvate formed in the cytoplasm can follow three pathways depending on oxygen availability. In the presence of oxygen, it is broken down in the mitochondria into carbon dioxide, water, and a large amount of energy (aerobic respiration). In the absence of oxygen, yeast converts it into ethanol and carbon dioxide, releasing less energy (anaerobic, fermentation). In human muscle cells lacking sufficient oxygen, it is converted into lactic acid, also releasing less energy.", keyPoints: ["With oxygen (mitochondria): CO2 + water + more energy", "Yeast, no oxygen: ethanol + CO2 + less energy", "Muscle cells, no oxygen: lactic acid + less energy"] },
  { id: 9, question: "Describe how gas exchange in plants differs between day and night.", answer: "At night, since photosynthesis is not occurring, the carbon dioxide produced by respiration is not consumed and is released as the main gas exchange event. During the day, the carbon dioxide generated by respiration is used up in photosynthesis, so no net CO2 is released; instead, the release of oxygen (a photosynthesis by-product) becomes the major visible gas exchange event.", keyPoints: ["Night: CO2 released (no photosynthesis to use it)", "Day: CO2 consumed by photosynthesis", "Day: O2 release becomes the main event"] },
  { id: 10, question: "Describe the pathway of air from the nostrils to the alveoli.", answer: "Air enters through the nostrils, where fine hairs and mucus filter out dust and germs. It then passes through the pharynx and larynx into the trachea, which is held open by rings of cartilage. The trachea divides into bronchi, which further branch into smaller bronchioles, finally ending in millions of tiny, thin-walled alveoli where actual gas exchange takes place.", keyPoints: ["Nostrils (filtered) -> pharynx -> larynx -> trachea", "Trachea -> bronchi -> bronchioles", "Bronchioles end in alveoli, site of gas exchange"] },
  { id: 11, question: "Describe the mechanism of breathing (inhalation and exhalation).", answer: "During inhalation, the ribs move upward and outward and the diaphragm contracts and flattens, enlarging the chest cavity; this drop in pressure draws air into the lungs. During exhalation, the ribs move down and inward and the diaphragm relaxes and domes upward, shrinking the chest cavity and pushing air out of the lungs.", keyPoints: ["Inhalation: ribs up, diaphragm flattens, cavity enlarges", "Exhalation: ribs down, diaphragm domes, cavity shrinks", "Pressure changes draw air in / push air out"] },
  { id: 12, question: "Explain why a respiratory pigment like haemoglobin is necessary in humans.", answer: "In a large organism like a human, diffusion alone is far too slow to carry oxygen from the lungs to distant tissues -- it would take around three years to reach the toes by diffusion alone. Haemoglobin, present in red blood cells, has a high affinity for oxygen and actively carries it through the bloodstream, delivering it quickly and efficiently to every part of the body.", keyPoints: ["Diffusion alone far too slow over body's distances", "Haemoglobin actively carries oxygen in blood", "Delivers oxygen quickly to distant tissues"] },
  { id: 13, question: "Describe the path of blood flow through the four chambers of the human heart.", answer: "Oxygen-rich blood from the lungs enters the left atrium, which contracts to push it into the left ventricle; the left ventricle then contracts powerfully to pump this oxygenated blood to the entire body. Deoxygenated blood returning from the body enters the right atrium, which contracts to push it into the right ventricle; the right ventricle then pumps this blood to the lungs to be oxygenated.", keyPoints: ["Left atrium -> left ventricle -> pumped to body", "Right atrium -> right ventricle -> pumped to lungs", "Valves prevent backflow at each stage"] },
  { id: 14, question: "Differentiate between arteries, veins, and capillaries.", answer: "Arteries carry blood away from the heart to the organs and have thick, elastic walls since the blood inside is under high pressure. Veins carry blood back to the heart from organs; their walls are thinner, and they contain valves to keep blood flowing in one direction since it is not under high pressure. Capillaries are the smallest vessels, with walls only one cell thick, allowing direct exchange of materials with body cells.", keyPoints: ["Arteries: away from heart, thick elastic walls", "Veins: to heart, thinner walls, valves", "Capillaries: one-cell-thick walls, material exchange"] },
  { id: 15, question: "Explain what blood pressure is and how hypertension develops.", answer: "Blood pressure is the force that circulating blood exerts against the walls of blood vessels, higher in arteries than in veins. Hypertension (high blood pressure) develops when arterioles constrict (narrow), increasing resistance to blood flow, which raises the pressure needed to push blood through them and can eventually damage or rupture blood vessels.", keyPoints: ["Blood pressure: force against vessel walls", "Hypertension caused by arteriole constriction", "Increased resistance raises pressure, risks rupture"] },
  { id: 16, question: "Describe the formation and function of lymph.", answer: "Lymph, or tissue fluid, forms when plasma, some proteins, and blood cells escape through the thin walls of capillaries into the spaces between cells. It is similar to plasma but colourless and contains less protein. Lymph drains into lymphatic capillaries and larger lymph vessels, eventually emptying into veins; it also carries digested fat absorbed from the intestine and drains excess fluid from tissues back into the blood.", keyPoints: ["Forms from plasma/protein/cells escaping capillaries", "Drains into lymph vessels, then into veins", "Carries absorbed fat; drains excess tissue fluid"] },
  { id: 17, question: "Explain how water is transported upward through the xylem in tall trees.", answer: "Roots actively absorb mineral ions from the soil, creating a concentration difference that draws water into the root xylem, generating root pressure that pushes water upward -- most significant at night. During the day, evaporation of water from leaf cells through open stomata (transpiration) creates a continuous suction that pulls water up through the xylem, called transpiration pull, which is the major driving force for water movement to great heights.", keyPoints: ["Root pressure pushes water up (mainly at night)", "Transpiration pull draws water up (mainly by day)", "Together explain water movement even in tall trees"] },
  { id: 18, question: "Explain the mechanism of translocation of food through phloem.", answer: "Translocation is the transport of soluble products of photosynthesis, mainly sucrose, through the phloem. Unlike xylem transport, this process uses energy: sucrose is actively transferred into phloem tissue using ATP, which raises the osmotic pressure inside and draws water in. This builds up pressure that pushes material from the phloem tissue toward tissues with lower pressure, allowing food to move to wherever the plant needs it -- both upward and downward.", keyPoints: ["Sucrose actively loaded into phloem using ATP", "Raises osmotic pressure, draws water in", "Pressure gradient moves food in either direction"] },
  { id: 19, question: "Describe the structure of the nephron and explain how urine is formed.", answer: "Each nephron has a cup-shaped Bowman's capsule enclosing a cluster of fine blood capillaries called the glomerulus, followed by a long coiled tubule. Blood pressure forces small molecules (water, glucose, amino acids, salts, urea) out of the glomerulus into the Bowman's capsule as filtrate, while blood cells and large proteins are held back. As this filtrate flows along the tubule, useful substances are selectively reabsorbed into the surrounding blood, leaving urine (containing urea, excess salts, and water) to flow into the collecting duct.", keyPoints: ["Glomerulus + Bowman's capsule filter blood", "Tubule selectively reabsorbs useful substances", "Remaining filtrate (urea, excess water/salts) becomes urine"] },
  { id: 20, question: "Explain how an artificial kidney (dialysis machine) works.", answer: "In hemodialysis, a patient's blood is passed through tubes made of a selectively permeable membrane, suspended in a tank of dialysing fluid that has the same osmotic pressure as blood but contains no nitrogenous wastes. Because of this concentration difference, nitrogenous wastes diffuse out of the blood into the dialysing fluid, and the purified blood is then pumped back into the patient. Unlike a real kidney, no reabsorption of useful substances occurs in this process.", keyPoints: ["Blood passed through selectively permeable tubing", "Dialysing fluid same osmotic pressure, no wastes", "Wastes diffuse out; no reabsorption occurs (unlike a real kidney)"] },
  { id: 21, question: "Explain why nitrogen is an essential raw material for plants and where it comes from.", answer: "Nitrogen is essential for plants mainly because it is required for the synthesis of proteins. Plants absorb nitrogen from the soil, mostly in the form of inorganic nitrates or nitrites, or as organic compounds prepared by certain bacteria that convert atmospheric nitrogen into a usable form.", keyPoints: ["Nitrogen needed for protein synthesis", "Absorbed as nitrates/nitrites from soil", "Also obtained via nitrogen-fixing bacteria"] },
  { id: 22, question: "Explain the significance of the experiment testing whether CO2 is necessary for photosynthesis (using KOH).", answer: "In this experiment, one potted plant is placed under a bell jar along with a watch glass of potassium hydroxide (KOH), which absorbs the CO2 present inside, while a second identical plant is placed under a bell jar without KOH. After a period in sunlight, the leaf from the KOH set-up shows little or no starch (negative test), while the other leaf shows starch, demonstrating that carbon dioxide is a necessary raw material for photosynthesis.", keyPoints: ["KOH absorbs CO2 inside the sealed bell jar", "Plant with KOH shows no/less starch", "Demonstrates CO2 is necessary for photosynthesis"] },
  { id: 23, question: "Explain why plants can survive with a slow-moving transport system, unlike most animals.", answer: "Plants have comparatively low energy needs since they do not move about, and a large part of their tissue is made of dead, non-living cells (like xylem vessels) that require no active maintenance. Because of this low energy demand, a relatively slow transport system is sufficient for plants, even to carry material over the large distances found in tall trees.", keyPoints: ["Plants have low energy needs (no locomotion)", "Much tissue is dead/non-living (e.g. xylem)", "Slow transport system is therefore sufficient"] },
  { id: 24, question: "Describe how fish are adapted to obtain oxygen from water.", answer: "Fish take in water through the mouth and force it out past the gills, thin, feathery structures richly supplied with blood vessels. As water flows past the gills, dissolved oxygen diffuses into the blood while carbon dioxide diffuses out into the water. Since water contains much less dissolved oxygen than air, fish must continuously pump large volumes of water past their gills, giving them a comparatively fast breathing rate.", keyPoints: ["Water taken in through mouth, passed over gills", "Gills are richly supplied with blood vessels", "Fast breathing compensates for low dissolved O2 in water"] },
  { id: 25, question: "Explain the difference between excretion in unicellular organisms and in complex multicellular organisms.", answer: "Unicellular organisms remove their waste products by simple diffusion directly into the surrounding water, since their entire cell surface is in contact with the environment. Complex multicellular organisms, whose internal cells are far from the body surface, instead use specialised excretory organs -- such as the kidneys in humans -- to collect and remove waste from the whole body.", keyPoints: ["Unicellular: waste diffuses directly into surroundings", "Multicellular: needs specialised excretory organs", "Example: kidneys in humans"] },
];

