export const BIOLOGY10_SELF_ASSESSMENT: QuizQuestion[] = [
  { id: 1, question: "A leaf is destarched, then half of it is covered with black paper and the whole plant is placed in sunlight for several hours. On testing with iodine, the covered half shows no colour change while the uncovered half turns blue-black. What does this specifically prove?", options: ["Chlorophyll is necessary for photosynthesis", "Light is necessary for photosynthesis", "Carbon dioxide is necessary for photosynthesis", "Water is necessary for photosynthesis"], correctAnswer: 1, explanation: "Both halves have chlorophyll and access to CO2/water; the only variable is light exposure, so the difference in starch formation proves light is necessary for photosynthesis." },
  { id: 2, question: "A plant is placed under a bell jar with a watch glass of KOH and given light. A control plant, otherwise identical, is placed under a bell jar with a watch glass of plain water. Both then test negative for starch. What is the most likely flaw?", options: ["KOH does not actually absorb CO2", "The plants were not destarched before the experiment", "Both jars were sealed, but neither had light", "Iodine was defective"], correctAnswer: 1, explanation: "If neither plant was destarched beforehand, a negative test in the control (which should show starch, since it has CO2) suggests the starch already present initially wasn't cleared first, or another basic setup step failed -- both testing negative when only the KOH plant should is the anomaly pointing to a destarching flaw." },
  { id: 3, question: "Which of the following correctly ranks these structures from SMALLEST scale to LARGEST scale?", options: ["Chloroplast, stoma, vein, leaf", "Stoma, chloroplast, vein, leaf", "Vein, leaf, stoma, chloroplast", "Leaf, vein, stoma, chloroplast"], correctAnswer: 0, explanation: "Chloroplasts are cell organelles (smallest), stomata are microscopic pores, veins are visible vascular strands, and the leaf is the largest, containing all the others." },
  { id: 4, question: "A plant's guard cells lose the ability to swell with water. What is the most direct consequence for the plant during the day?", options: ["The plant will photosynthesise faster", "Stomata will remain closed, reducing CO2 uptake and photosynthesis", "The plant will lose water faster than normal", "Xylem will stop transporting water"], correctAnswer: 1, explanation: "Guard cells must swell with water to open the stomatal pore; if they cannot swell, stomata stay closed, blocking CO2 entry and reducing photosynthesis." },
  { id: 5, question: "Which sequence correctly places these nutrition types from 'most independent of other organisms' to 'most dependent on a living host'?", options: ["Parasitic, saprophytic, autotrophic, holozoic", "Autotrophic, holozoic, saprophytic, parasitic", "Holozoic, autotrophic, parasitic, saprophytic", "Saprophytic, parasitic, holozoic, autotrophic"], correctAnswer: 1, explanation: "Autotrophs need no other organism at all; holozoic feeders eat other organisms (dead or alive, not necessarily a living host); saprophytes need dead/decaying matter; parasites need a living host specifically." },
  { id: 6, question: "A tapeworm living in a human intestine absorbs digested nutrients directly through its body surface and has no digestive system of its own. This is most consistent with which nutritional adaptation?", options: ["It relies on the host's digestion, needing only absorption structures itself", "It is autotrophic", "It uses pseudopodia like Amoeba", "It performs photosynthesis internally"], correctAnswer: 0, explanation: "As a parasite living inside an already-digesting environment, the tapeworm doesn't need its own digestive machinery -- just efficient absorption -- since the host has already broken the food down." },
  { id: 7, question: "If Amoeba's plasma membrane suddenly became rigid and could not form pseudopodia, what would be most immediately affected?", options: ["Its respiration", "Its ability to obtain food", "Its excretion of CO2", "Its cell division only"], correctAnswer: 1, explanation: "Amoeba depends entirely on flexible pseudopodia to engulf food particles; a rigid membrane would directly prevent this feeding mechanism." },
  { id: 8, question: "Which of the following would you expect to have the LEAST digestive enzyme activity in its secretions?", options: ["Saliva", "Gastric juice", "Bile", "Pancreatic juice"], correctAnswer: 2, explanation: "Bile contains no digestive enzymes -- its role is to emulsify fats (physically breaking large globules into smaller ones) and neutralise stomach acid, not to chemically digest anything." },
  { id: 9, question: "A person has a condition where their gall bladder is removed and bile flows continuously in small amounts directly into the intestine rather than being stored and released in a burst after a fatty meal. Which digestive process would most likely become less efficient right after a large fatty meal?", options: ["Protein digestion by pepsin", "Fat emulsification, since less bile is available at once when most needed", "Starch digestion by amylase", "Water absorption in the large intestine"], correctAnswer: 1, explanation: "Without bile storage and burst-release timed to a fatty meal, there may not be enough bile available at once to properly emulsify a large quantity of fat, reducing the efficiency of fat digestion right after eating." },
  { id: 10, question: "Which of these correctly matches the enzyme to BOTH its source organ and its substrate?", options: ["Pepsin -- pancreas -- fats", "Trypsin -- pancreas -- proteins", "Salivary amylase -- stomach -- starch", "Lipase -- liver -- fats"], correctAnswer: 1, explanation: "Trypsin is secreted by the pancreas and digests proteins. Pepsin is from the stomach (not pancreas) and digests protein; salivary amylase is from salivary glands (not stomach); lipase is from the pancreas (not liver)." },
  { id: 11, question: "A person's small intestine is surgically shortened significantly. What is the most likely direct consequence?", options: ["Faster digestion of starch in the mouth", "Reduced absorption of digested nutrients due to less villi surface area available", "Increased bile production", "No effect, since digestion is completed in the stomach"], correctAnswer: 1, explanation: "Shortening the small intestine reduces the total villi surface area available, directly reducing how much digested food can be absorbed into the blood." },
  { id: 12, question: "Glucose is broken down to pyruvate in the cytoplasm regardless of oxygen availability. What does this tell you about this first step?", options: ["It is an aerobic-only process", "It is common to both aerobic and anaerobic respiration", "It occurs only in mitochondria", "It requires haemoglobin"], correctAnswer: 1, explanation: "Since this step happens the same way whether or not oxygen is present, it must be a shared first step for both aerobic and anaerobic pathways, before they diverge." },
  { id: 13, question: "If a cell's mitochondria were destroyed but its cytoplasm remained functional, which process could the cell still carry out?", options: ["Aerobic respiration, in full", "Anaerobic breakdown of glucose to pyruvate and beyond (e.g. lactic acid), but not full aerobic breakdown", "No respiration whatsoever", "Photosynthesis"], correctAnswer: 1, explanation: "Glycolysis (glucose to pyruvate) and further anaerobic steps (like lactic acid formation) occur in the cytoplasm, so they could continue without mitochondria, but the mitochondria-dependent aerobic pathway would be lost." },
  { id: 14, question: "Which of the following organisms/cells is LEAST likely to rely on anaerobic respiration under normal, healthy conditions?", options: ["Yeast during fermentation", "Human muscle cells during a sprint", "A well-oxygenated human liver cell at rest", "Bacteria in an oxygen-poor environment"], correctAnswer: 2, explanation: "A resting, well-oxygenated liver cell has ample oxygen and would normally use efficient aerobic respiration rather than the less efficient anaerobic pathway." },
  { id: 15, question: "Comparing energy yield: which of the following correctly ranks respiration types from LEAST to MOST energy released per glucose molecule?", options: ["Aerobic < anaerobic (yeast) < anaerobic (muscle)", "Anaerobic (yeast) = anaerobic (muscle) < aerobic", "Aerobic < anaerobic (yeast) = anaerobic (muscle)", "Anaerobic (muscle) < aerobic < anaerobic (yeast)"], correctAnswer: 1, explanation: "Both anaerobic pathways (fermentation in yeast, lactic acid in muscle) release similarly small amounts of energy compared to the much larger energy release from complete aerobic breakdown." },
  { id: 16, question: "A student claims 'CO2 is dissolved and transported in blood the same way O2 is, bound tightly to haemoglobin.' What is wrong with this claim?", options: ["Nothing, it is correct", "CO2 is mostly transported dissolved in plasma, not bound to haemoglobin like O2", "O2 is not transported by haemoglobin at all", "CO2 is not produced by the body"], correctAnswer: 1, explanation: "Unlike oxygen, which binds to haemoglobin, CO2 is much more soluble in water and is mostly transported simply dissolved in the blood plasma." },
  { id: 17, question: "If the surface area of the alveoli in a person's lungs were somehow cut in half, what would be the most direct expected effect?", options: ["Faster CO2 production", "Reduced efficiency of oxygen and carbon dioxide exchange", "Increased haemoglobin count automatically", "No change, since alveoli are not important for gas exchange"], correctAnswer: 1, explanation: "Since alveolar surface area is what enables efficient gas exchange, halving it would directly reduce how efficiently oxygen and CO2 can be exchanged with the blood." },
  { id: 18, question: "Which structure prevents the trachea from collapsing when air pressure inside changes during breathing?", options: ["Alveoli", "Rings of cartilage", "Diaphragm", "Bronchioles"], correctAnswer: 1, explanation: "The rings of cartilage in the trachea's walls keep it rigid enough to stay open despite pressure changes during breathing." },
  { id: 19, question: "A fish is moved from cold, oxygen-rich water to warm, oxygen-poor water. What change in its behaviour would you most expect?", options: ["A decrease in breathing rate", "An increase in breathing rate to compensate for lower dissolved oxygen", "No change at all", "The fish would stop using its gills"], correctAnswer: 1, explanation: "With less dissolved oxygen available, the fish must pump more water past its gills per unit time to obtain sufficient oxygen, increasing its breathing rate." },
  { id: 20, question: "Which of these best explains why terrestrial animals generally have a slower breathing rate than aquatic animals of similar size?", options: ["Terrestrial animals have smaller lungs", "Air contains a much higher concentration of oxygen than water does", "Terrestrial animals need less oxygen overall", "Aquatic animals have more haemoglobin"], correctAnswer: 1, explanation: "Since air has far more available oxygen than water, terrestrial animals can obtain enough oxygen with a slower breathing rate compared to aquatic animals extracting oxygen from water." },
  { id: 21, question: "In the human heart, if the valve between the left atrium and left ventricle failed to close properly, what would most likely happen during ventricular contraction?", options: ["Blood would flow efficiently only to the body", "Some blood would flow backward into the left atrium instead of being pumped to the body", "The right side of the heart would be affected first", "Nothing, since this valve has no functional role"], correctAnswer: 1, explanation: "Valves prevent backflow; if the valve between left atrium and left ventricle failed, some blood would leak backward into the atrium during ventricular contraction instead of all of it going to the body." },
  { id: 22, question: "Which chamber of the human heart has to generate the GREATEST pumping force, and why?", options: ["Right atrium, because it receives blood first", "Left ventricle, because it must pump blood to the entire body", "Right ventricle, because it pumps to the lungs only", "Left atrium, because it receives oxygenated blood"], correctAnswer: 1, explanation: "The left ventricle must generate enough pressure to push blood through the entire systemic circulation (the whole body), which is a much larger and more resistant circuit than the short trip to the lungs -- so it has the thickest, most muscular wall." },
  { id: 23, question: "A reptile with a three-chambered heart allows partial mixing of oxygenated and deoxygenated blood. Why is this generally NOT fatal, unlike it would be for a mammal?", options: ["Reptiles do not need oxygen", "Reptiles' body temperature depends on the environment, so they have lower, more variable energy demands", "Reptiles have no lungs", "Reptile blood does not carry oxygen at all"], correctAnswer: 1, explanation: "Since reptiles are ectothermic (body temperature depends on environment) rather than needing to constantly generate heat internally, their lower and more variable energy demands can tolerate a somewhat less efficient oxygen supply from blood mixing." },
  { id: 24, question: "Which of the following, if it occurred, would DIRECTLY reduce systolic blood pressure the most?", options: ["Increasing heart rate significantly", "Widening (dilating) arterioles, reducing resistance to blood flow", "Narrowing arterioles", "Removing all valves from veins"], correctAnswer: 1, explanation: "Widening arterioles reduces resistance to blood flow, which directly lowers the pressure needed to push blood through them, reducing blood pressure -- the opposite of what causes hypertension." },
  { id: 25, question: "Why do capillaries, despite being the narrowest blood vessels, have walls only one cell thick rather than thick and elastic like arteries?", options: ["To withstand very high pressure", "To allow efficient diffusion of materials directly with surrounding cells", "Because they carry no blood cells", "To store extra blood"], correctAnswer: 1, explanation: "Capillaries exist specifically to let materials diffuse between blood and tissue cells; thin, one-cell-thick walls minimise the diffusion distance, maximising exchange efficiency." },
  { id: 26, question: "A person's veins lose their valves due to a medical condition. What is the most likely direct consequence?", options: ["Blood would flow more efficiently toward the heart", "Blood could pool or flow backward, since nothing prevents backflow in low-pressure veins", "Arterial pressure would rise immediately", "Nothing, since valves in veins are not important"], correctAnswer: 1, explanation: "Venous blood is not under high pressure, so valves are what actually keep it moving one-directionally toward the heart; without them, blood could pool or flow backward, especially against gravity." },
  { id: 27, question: "Which of the following is TRUE about lymph compared to blood plasma?", options: ["Lymph has more protein than plasma", "Lymph is essentially similar to plasma, but colourless and with less protein", "Lymph contains no cells at all, unlike plasma", "Lymph and plasma have no relationship"], correctAnswer: 1, explanation: "Lymph forms from plasma and cells that escape through capillary pores, and is similar to plasma but colourless and lower in protein content." },
  { id: 28, question: "If the lymphatic system stopped draining excess fluid from tissue spaces back into the blood, what condition would most likely result?", options: ["Dehydration", "Swelling (accumulation of fluid) in tissues", "Excess blood clotting", "Immediate cardiac arrest"], correctAnswer: 1, explanation: "One key function of lymph is draining excess fluid from tissue spaces back into the blood; without this, fluid would accumulate in tissues, causing swelling." },
  { id: 29, question: "In xylem transport, which of the following is NOT a driving force for water movement?", options: ["Root pressure", "Transpiration pull", "Active use of ATP energy to pump water molecules", "Suction from evaporating water at the leaf surface"], correctAnswer: 2, explanation: "Xylem transport is a purely physical process (root pressure and transpiration pull); it does NOT use ATP energy, unlike phloem transport." },
  { id: 30, question: "At night, when stomata are closed and transpiration is minimal, what becomes the primary force moving water up the xylem?", options: ["Transpiration pull", "Root pressure", "Gravity", "No water movement occurs at night"], correctAnswer: 1, explanation: "With stomata closed at night, transpiration pull is minimal, so root pressure (from active ion uptake by roots) becomes the more significant driving force." },
  { id: 31, question: "Sucrose is loaded into phloem sieve tubes using ATP, which then draws in water by osmosis. What does this pressure increase ultimately achieve?", options: ["It stops all further phloem transport", "It pushes material toward tissues of lower pressure, moving food to where it's needed", "It converts sucrose back into starch immediately", "It has no functional purpose"], correctAnswer: 1, explanation: "The pressure built up by water entering via osmosis pushes phloem contents toward regions of lower pressure, which is how food gets moved to wherever the plant currently needs it." },
  { id: 32, question: "Unlike xylem, phloem can transport material in BOTH directions (up or down the plant). What makes this possible?", options: ["Phloem has valves like veins", "Active, energy-driven loading of sucrose lets pressure build wherever needed, directing flow accordingly", "Phloem is not made of living cells", "Gravity alone determines the direction"], correctAnswer: 1, explanation: "Because phloem transport is actively driven by energy-dependent loading of sucrose (rather than being passively driven one way like xylem), pressure gradients can be set up in either direction depending on where food is currently needed." },
  { id: 33, question: "A plant is grown in nitrogen-deficient soil. Which specific biological process would be most directly impaired?", options: ["Water absorption by roots", "Protein synthesis, since nitrogen is essential for making proteins", "Gas exchange through stomata", "Xylem water transport"], correctAnswer: 1, explanation: "Nitrogen is essential specifically for protein synthesis; a nitrogen deficiency would most directly impair the plant's ability to build proteins." },
  { id: 34, question: "In the nephron, which structure is primarily responsible for RETAINING blood cells and large proteins in the blood, rather than letting them into the filtrate?", options: ["The collecting duct", "The glomerulus/Bowman's capsule filtration barrier", "The ureter", "The urinary bladder"], correctAnswer: 1, explanation: "The filtration that occurs at the glomerulus (into the Bowman's capsule) only lets small molecules pass into the filtrate; blood cells and large proteins are too big to pass and are retained in the blood." },
  { id: 35, question: "If the reabsorption function of the nephron's tubule stopped working entirely, but filtration still occurred normally, what would happen to urine output?", options: ["Urine output would decrease sharply", "Urine output would increase dramatically, since almost nothing filtered would be reabsorbed", "There would be no change", "Urine would stop being produced entirely"], correctAnswer: 1, explanation: "Since normally most of the ~180 L/day of filtrate is reabsorbed and only 1-2 L/day is excreted, losing all reabsorption would cause urine output to increase dramatically toward that much larger filtered volume." },
  { id: 36, question: "A person drinks an unusually large amount of water. How would you expect their kidneys to respond?", options: ["Reabsorb more water than usual, producing less, more concentrated urine", "Reabsorb less water than usual, producing more, more dilute urine", "Stop filtering blood entirely", "Produce no change in urine at all"], correctAnswer: 1, explanation: "With excess water in the body, the nephron reabsorbs less water back into the blood, resulting in a larger volume of more dilute urine to remove the extra water." },
  { id: 37, question: "Which of these correctly explains why alveoli and nephrons are both described as having a huge combined surface area despite each individual unit being microscopic?", options: ["Each one is unusually large on its own", "There are millions of them in each organ, and their individual small size adds up to an enormous total area", "They are connected directly to each other", "Surface area is irrelevant to their function"], correctAnswer: 1, explanation: "It is the sheer number of these microscopic units (millions of alveoli, millions of nephrons) that adds up to an enormous total surface area, not the size of any single unit." },
  { id: 38, question: "Which of the following is a functional difference (not similarity) between alveoli and nephrons?", options: ["Both are thin-walled", "Both are surrounded by blood capillaries", "Alveoli exchange gases; nephrons filter blood and form urine", "Both are present in very large numbers"], correctAnswer: 2, explanation: "While alveoli and nephrons share many structural similarities (thin walls, capillary networks, huge numbers), their actual functions differ: gas exchange versus blood filtration/urine formation." },
  { id: 39, question: "Why does a plant NOT need an active, energy-consuming excretory organ the way animals need kidneys?", options: ["Plants produce no waste at all", "Plant waste products can largely be handled by storage, shedding, or passive release, given plants' low energy needs", "Plants have kidneys too, just smaller", "Plants never accumulate any toxic substances"], correctAnswer: 1, explanation: "Because plants have much lower energy needs and different types of waste, passive strategies (storage in vacuoles, shedding leaves, gas release, excretion into soil) are sufficient without needing an active filtering organ like a kidney." },
  { id: 40, question: "Which of the following would be the most direct evidence that transpiration, not root pressure, is the dominant force pulling water up a tree during a hot, sunny afternoon?", options: ["Water movement is fastest at night", "Water movement slows dramatically if all stomata are experimentally blocked during the day", "Root pressure alone can push water to any height", "There is no way to distinguish the two forces"], correctAnswer: 1, explanation: "If blocking stomata (which are essential for transpiration) sharply reduces water movement during the day, this shows transpiration pull -- not root pressure -- is the dominant daytime driving force." },
  { id: 41, question: "A patient's haemoglobin level is measured and found to be significantly below normal. Which symptom would you MOST expect as a direct result?", options: ["Excess blood clotting", "Fatigue and breathlessness, due to reduced oxygen-carrying capacity of blood", "Increased blood pressure only", "Improved digestion"], correctAnswer: 1, explanation: "Lower haemoglobin means less oxygen can be carried to tissues, directly causing fatigue and breathlessness since cells cannot generate enough energy through aerobic respiration." },
  { id: 42, question: "Which of these sequences correctly traces a molecule of oxygen from the air to a muscle cell in the leg?", options: ["Alveoli -> haemoglobin in blood -> heart -> arteries -> capillaries -> muscle cell", "Trachea -> muscle cell directly, bypassing blood", "Stomach -> intestine -> blood -> muscle cell", "Kidney -> ureter -> muscle cell"], correctAnswer: 0, explanation: "Oxygen diffuses into blood at the alveoli, binds haemoglobin, is pumped by the heart through arteries and then capillaries, where it finally diffuses into the muscle cell." },
  { id: 43, question: "Comparing digestion in the mouth and stomach, which statement is correct?", options: ["Both digest starch using the same enzyme", "The mouth mainly starts starch digestion; the stomach mainly digests protein, in an acidic environment", "The stomach digests starch; the mouth digests protein", "Neither organ performs any digestion, only mechanical breakdown"], correctAnswer: 1, explanation: "The mouth's salivary amylase begins starch digestion in a near-neutral environment, while the stomach's pepsin digests protein in a strongly acidic environment created by HCl." },
  { id: 44, question: "If bile production stopped completely but all other digestive secretions remained normal, which nutrient's digestion would be most impaired?", options: ["Starch", "Protein", "Fat, since bile's emulsification is a key step before lipase can act efficiently", "Water absorption"], correctAnswer: 2, explanation: "Bile does not digest fat itself, but its emulsification step is what allows lipase to act efficiently on a greatly increased fat surface area; without it, fat digestion would be far less efficient." },
  { id: 45, question: "A person has abnormally high stomach acid production (excess HCl). Besides causing 'acidity' discomfort, what OTHER digestive process could this most directly support (in excess)?", options: ["Starch digestion in the mouth", "Pepsin's protein-digesting activity, since HCl creates the acidic medium pepsin needs", "Bile emulsification of fats", "Water absorption in the large intestine"], correctAnswer: 1, explanation: "HCl's core digestive role is creating the acidic medium that pepsin needs to digest proteins -- so excess HCl is directly tied to (though not necessarily beneficial for) this process." },
  { id: 46, question: "Which of the following best explains why 'peristalsis' is essential throughout the entire alimentary canal, not just the oesophagus?", options: ["It only helps swallowing", "It is the rhythmic muscular contraction that pushes food/waste forward through every part of the canal, from mouth to anus", "It only occurs in the stomach", "It replaces the need for digestive enzymes"], correctAnswer: 1, explanation: "Peristaltic movements occur throughout the alimentary canal and are what actually propel food and waste material forward at every stage, not just during swallowing." },
  { id: 47, question: "Which pairing correctly matches a structure with its PRIMARY described role in this chapter?", options: ["Xylem -- food transport", "Nephron -- gas exchange", "Alveoli -- gas exchange", "Phloem -- water transport"], correctAnswer: 2, explanation: "Alveoli are correctly matched to gas exchange. Xylem carries water (not food); nephrons filter blood/form urine (not gas exchange); phloem carries food (not water)." },
  { id: 48, question: "Which of these four processes does NOT directly require a transportation system in a large multicellular organism?", options: ["Delivering oxygen to internal cells", "Carrying digested food to all body cells", "Removing carbon dioxide and nitrogenous waste from cells", "A single-celled organism exchanging gases directly with its environment"], correctAnswer: 3, explanation: "A single-celled organism's entire surface is in contact with its environment, so it exchanges gases directly by diffusion, without needing an internal transport system -- unlike the other three processes, which are why multicellular organisms need one." },
  { id: 49, question: "Considering both plants and humans, which statement correctly compares their transport systems?", options: ["Both use a muscular heart to pump fluid", "Human transport uses one pumping organ (the heart); plant transport instead relies on physical forces (root pressure, transpiration pull) and active loading (in phloem), with no central pump", "Plants have faster transport than humans", "Neither system involves any use of energy"], correctAnswer: 1, explanation: "Unlike the human circulatory system, which is driven by the heart as a central pump, plants have no such pump -- xylem relies on physical forces, and phloem relies on localised active loading of sucrose, not a central pumping organ." },
  { id: 50, question: "A student argues: 'Since both aerobic and anaerobic respiration start with glucose being converted to pyruvate, they are essentially the same process.' What is the strongest counterargument?", options: ["They are indeed the same process", "They diverge significantly after that shared first step -- in energy released, end products, and whether oxygen and mitochondria are involved", "Anaerobic respiration does not involve glucose at all", "Aerobic respiration does not occur in cells"], correctAnswer: 1, explanation: "Although both pathways share the same first step (glucose to pyruvate in the cytoplasm), they diverge sharply afterward in energy yield, end products (CO2+water vs. ethanol/lactic acid), and location (mitochondria vs. cytoplasm only) -- so calling them 'essentially the same' overlooks these major differences." },
];
